package com.shopsphere.service; import com.shopsphere.dto.AuthDtos.PaymentResponse; import com.shopsphere.entity.*; import com.shopsphere.exception.ApiException; import com.shopsphere.repository.*; import com.shopsphere.security.CurrentUser; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class PaymentService {private final PaymentRepository payments;private final OrderRepository orders;private final CurrentUser current;public PaymentService(PaymentRepository p,OrderRepository o,CurrentUser c){payments=p;orders=o;current=c;} @Transactional public PaymentResponse create(UUID orderId,Authentication a){Order o=orders.findById(orderId).orElseThrow(()->new ApiException("ORDER_NOT_FOUND","Order not found"));if(!o.getUser().getId().equals(current.get(a).getId()))throw new ApiException("FORBIDDEN","Order does not belong to user");if(payments.findByOrder(o).isPresent())return map(payments.findByOrder(o).get());Payment p=new Payment();p.setOrder(o);p.setReference("PAY-"+UUID.randomUUID());p.setAmount(o.getTotal());p.setStatus(PaymentStatus.CREATED);payments.save(p);return map(p);} @Transactional public PaymentResponse confirm(String ref){Payment p=payments.findByReference(ref).orElseThrow();p.setStatus(PaymentStatus.SUCCESS);p.getOrder().setStatus(OrderStatus.PROCESSING);return map(p);} private PaymentResponse map(Payment p){return new PaymentResponse(p.getId(),p.getReference(),p.getStatus().name(),p.getAmount());}}
